namespace ghidra.formats.gfilesystem.crypto;



using ghidra.formats.gfilesystem;
using ghidra.framework.generic.auth;

/**
 * Caches passwords used to unlock a file.
 * <p>
 * Threadsafe.
 */
public class CachedPasswordProvider : PasswordProvider {


	private Map<string, List<CryptoRec>> values = new();
	private int count;

	/**
	 * Adds a password / file combo to the cache.
	 * 
	 * @param fsrl {@link FSRL} file
	 * @param password password to unlock the file.  Specified {@link Password} is
	 * only copied, clearing is still callers responsibility
	 */
	public void addPassword(FSRL fsrl, Password password) {
		CryptoRec rec = new CryptoRec();
		rec.fsrl = fsrl;
		rec.value = password.clone();
		addRec(rec);
	}


	private void addRec(CryptoRec rec) {
		// index the record by its full FSRL, a simplified FSRL, its plain filename, and any MD5 
		string fsrlStr = rec.fsrl.toString();
		bool isNewValue =
			addIfUnique(values.computeIfAbsent(fsrlStr, x => new()), rec);

		string fsrlStr2 = rec.fsrl.toPrettyString();
		if (!fsrlStr2.equals(fsrlStr)) {
			addIfUnique(values.computeIfAbsent(fsrlStr2, x => new()), rec);
		}

		addIfUnique(values.computeIfAbsent(rec.fsrl.getName(), x => new()), rec);

		if (rec.fsrl.getMD5() != null) {
			addIfUnique(values.computeIfAbsent(rec.fsrl.getMD5(), x => new()), rec);
		}

		if (isNewValue) {
			count++;
		}
	}

	private bool addIfUnique(List<CryptoRec> recs, CryptoRec newRec) {
		foreach (CryptoRec rec in recs) {
			if (rec.value.equals(newRec.value)) {
				return false;
			}
		}
		recs.add(newRec);
		return true;
	}

	/**
	 * Remove all cached information.
	 */
	public void clearCache() {
		values.clear();
		count = 0;
	}

	/**
	 * Returns the number of items in cache
	 * 
	 * @return number of items in cache
	 */
	public int getCount() {
		return count;
	}

	/* @Override */
	public Iterator<Password> getPasswordsFor(FSRL fsrl, string prompt,
			Session session) {
		Set<CryptoRec> uniqueFoundRecs = new();
		uniqueFoundRecs.addAll(values.getOrDefault(fsrl.toString(), Collections.emptyList()));
		uniqueFoundRecs.addAll(values.getOrDefault(fsrl.toPrettyString(), Collections.emptyList()));
		uniqueFoundRecs.addAll(values.getOrDefault(fsrl.getName(), Collections.emptyList()));
		if (fsrl.getMD5() != null) {
			uniqueFoundRecs.addAll(values.getOrDefault(fsrl.getMD5(), Collections.emptyList()));
		}

		List<Password> results = new();
		foreach (CryptoRec rec in uniqueFoundRecs) {
			results.add(rec.value);
		}

		// Use an iterator that clones the values before giving them to the caller
		// so our internal values don't get cleared
		return new CloningPasswordIterator(results.iterator());
	}

	private static class CryptoRec {
		FSRL fsrl;
		Password value;
	}

	private class CloningPasswordIterator : Iterator<Password> {
		Iterator<Password> @delegate;

		CloningPasswordIterator(Iterator<Password> it) {
			this.@delegate = it;
		}

		/* @Override */
		public bool hasNext() {
			return @delegate.hasNext();
		}

		/* @Override */
		public Password next() {
			Password result = @delegate.next();
			return result.clone();
		}

	}

}
